for r in range(10):
    for c in range(20):
        d=min(r,9-r,c,19-c)
        grid[r][c]=7 if d%2==0 else 8
grid[10]=[6]*20
for r in range(11,20):
    grid[r][7]=6
    for c in range(7):
        d=min(r-11,19-r,c,6-c)
        grid[r][c]=[2,0,1][d%3]
